def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []

    adj_sets = [set(neighbors) for neighbors in adj]

    def greedy_color(order):
        colors = [-1] * n
        for v in order:
            used = set()
            for u in adj_sets[v]:
                if colors[u] >= 0:
                    used.add(colors[u])
            c = 0
            while c in used:
                c += 1
            colors[v] = c
        return colors

    def count_colors(colors):
        return max(colors) + 1 if colors else 0

    def dsatur_order():
        colored = [False] * n
        saturation = [0] * n
        degree = [len(adj[v]) for v in range(n)]
        neighbor_colors = [set() for _ in range(n)]
        colors = [-1] * n
        order = []

        for _ in range(n):
            best = -1
            best_sat = -1
            best_deg = -1
            for v in range(n):
                if not colored[v]:
                    if (saturation[v] > best_sat or 
                        (saturation[v] == best_sat and degree[v] > best_deg)):
                        best = v
                        best_sat = saturation[v]
                        best_deg = degree[v]

            used = set()
            for u in adj_sets[best]:
                if colors[u] >= 0:
                    used.add(colors[u])
            c = 0
            while c in used:
                c += 1
            colors[best] = c
            colored[best] = True
            order.append(best)

            for u in adj_sets[best]:
                if not colored[u]:
                    if c not in neighbor_colors[u]:
                        neighbor_colors[u].add(c)
                        saturation[u] += 1

        return colors, order

    def reorder_by_color_class(colors, num_colors):
        classes = [[] for _ in range(num_colors)]
        for v in range(n):
            classes[colors[v]].append(v)
        order = []
        for cls in classes:
            order.extend(cls)
        return order

    def reorder_largest_first(colors, num_colors):
        classes = [[] for _ in range(num_colors)]
        for v in range(n):
            classes[colors[v]].append(v)
        classes.sort(key=len, reverse=True)
        order = []
        for cls in classes:
            order.extend(cls)
        return order

    def reorder_random_classes(colors, num_colors):
        classes = [[] for _ in range(num_colors)]
        for v in range(n):
            classes[colors[v]].append(v)
        random.shuffle(classes)
        order = []
        for cls in classes:
            order.extend(cls)
        return order

    # Initial coloring with DSatur
    best_colors, dsatur_ord = dsatur_order()
    best_num = count_colors(best_colors)

    # Also try greedy with degree ordering
    degree_order = sorted(range(n), key=lambda v: len(adj[v]), reverse=True)
    c2 = greedy_color(degree_order)
    if count_colors(c2) < best_num:
        best_colors = c2
        best_num = count_colors(c2)

    # Iterated greedy passes
    current_colors = list(best_colors)
    current_num = best_num

    max_iterations = 50
    for iteration in range(max_iterations):
        if current_num <= 1:
            break

        # Choose reordering strategy
        r = iteration % 4
        if r == 0:
            order = reorder_largest_first(current_colors, current_num)
        elif r == 1:
            order = reorder_by_color_class(current_colors, current_num)
        elif r == 2:
            order = reorder_random_classes(current_colors, current_num)
        else:
            order = list(range(n))
            random.shuffle(order)

        new_colors = greedy_color(order)
        new_num = count_colors(new_colors)

        if new_num < best_num:
            best_colors = list(new_colors)
            best_num = new_num

        if new_num <= current_num:
            current_colors = new_colors
            current_num = new_num
        elif random.random() < 0.1:
            current_colors = new_colors
            current_num = new_num

    return best_colors

