                                    # Now try to recolor v
                                    neighbor_c2 = {colors[nb2] for nb2 in adj_sets[v]}
                                    if c not in neighbor_c2:
                                        colors[v] = c
                                        recolored = True
                                        break
                                    else:
                                        # Undo swap
                                        for u in chain:
