            c = 0
            nc = neighbor_colors[v]
            while c in nc:
                c += 1
            colors[v] = c
            for u in adj[v]:
                neighbor_colors[u].add(c)
        return colors

    def dsatur_color(noise=0.0):
        colors = [-1] * n
        saturation = [0] * n
        degree = [len(adj[v]) for v in range(n)]
        neighbor_color_sets = [set() for _ in range(n)]
        colored = 0
        while colored < n:
            best = -1; best_sat = -1; best_deg = -1; best_r = -1.0
            for v in range(n):
                if colors[v] != -1: continue
                s = saturation[v]; d = degree[v]
                r = random.random() if noise > 0 else 0.0
                if s > best_sat or (s == best_sat and d > best_deg) or (s == best_sat and d == best_deg and r > best_r):
                    best = v; best_sat = s; best_deg = d; best_r = r
            v = best
            c = 0
            nc = neighbor_color_sets[v]
            while c in nc: c += 1
            colors[v] = c; colored += 1
            for u in adj[v]:
                if colors[u] == -1 and c not in neighbor_color_sets[u]:
                    neighbor_color_sets[u].add(c); saturation[u] += 1
        return colors

    def try_eliminate_color(colors, target_color):
        # Try to recolor all vertices with target_color using lower colors
        # via Kempe chain swaps
        colors = colors[:]
        victims = [v for v in range(n) if colors[v] == target_color]
        for v in victims:
            if colors[v] != target_color:
                continue
            neighbor_cols = set(colors[u] for u in adj[v])
            # Try direct recolor first
            for c in range(target_color):
                if c not in neighbor_cols:
                    colors[v] = c
                    break
            else:
                # Try Kempe chain swap: swap colors a and b in connected component
                swapped = False
                for a in range(target_color):
                    if a in neighbor_cols:
