                                        chain.append(u)
                                        for w in adj[u]:
                                            if w not in visited and (colors[w] == a or colors[w] == b):
                                                stack.append(w)
                                # Check if swap is safe (v gets color b)
                                new_col = {u: (b if colors[u] == a else a) for u in chain}
                                # Verify no conflicts
                                ok = True
                                for u in chain:
                                    nc = new_col[u]
                                    for w in adj[u]:
