                                            ok = False; break
                                    if not ok: break
                                if ok and new_col.get(v) == b:
                                    for u in chain:
                                        colors[u] = new_col[u]
                                    swapped = True; break
                        if swapped: break
        # Check if target color eliminated
        if all(colors[v] != target_color for v in range(n)):
            return colors
        return None

    def improve(colors):
        num_colors = max(colors) + 1
        for target in range(num_colors - 1, 0, -1):
            result = try_eliminate_color(colors, target)
            if result is not None:
                colors = result
                num_colors = target
        return colors

