def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []

    adj_sets = [set(a) for a in adj]
    degree = [len(adj[v]) for v in range(n)]

    def dsatur_color(noise=0.0):
        colors = [-1] * n
        sat = [0] * n
        nc = [set() for _ in range(n)]
        uncolored = set(range(n))
        while uncolored:
            if noise > 0:
                best = max(uncolored, key=lambda v: (sat[v], degree[v], random.random()))
            else:
                best = max(uncolored, key=lambda v: (sat[v], degree[v]))
            c = 0
            while c in nc[best]:
                c += 1
            colors[best] = c
            uncolored.remove(best)
            for u in adj[best]:
                if colors[u] == -1 and c not in nc[u]:
                    nc[u].add(c)
                    sat[u] += 1
        return colors

    def rlf_color():
        colors = [-1] * n
        cur = 0
        uncolored = set(range(n))
        while uncolored:
            candidates = set(uncolored)
            excluded = set()
            iset = []
            start = max(candidates, key=lambda v: sum(1 for u in adj[v] if u in uncolored))
            iset.append(start)
            candidates.discard(start)
            for u in adj[start]:
                if u in candidates:
                    candidates.discard(u)
                    excluded.add(u)
            while candidates:
                v = max(candidates, key=lambda x: (
                    sum(1 for u in adj[x] if u in excluded),
                    -sum(1 for u in adj[x] if u in candidates)
                ))
                iset.append(v)
                candidates.discard(v)
                for u in adj[v]:
                    if u in candidates:
                        candidates.discard(u)
                        excluded.add(u)
            for v in iset:
                colors[v] = cur
                uncolored.discard(v)
            cur += 1
        return colors

    def kempe_reduce(colors):
        colors = colors[:]
        for _ in range(40):
            num_colors = max(colors) + 1
            if num_colors <= 1:
                break
            max_c = num_colors - 1
            high_verts = [v for v in range(n) if colors[v] == max_c]
            if not high_verts:
                break
            all_done = True
            for v in high_verts:
                if colors[v] != max_c:
                    continue
                forbidden = set(colors[u] for u in adj[v])
                # Direct recolor
                placed = False
                for c in range(max_c):
                    if c not in forbidden:
                        colors[v] = c
                        placed = True
                        break
                if placed:
                    continue
                # Kempe chain swap
                swapped = False
                lower = list(range(max_c))
                random.shuffle(lower)
                for c in lower:
                    # BFS Kempe chain of colors max_c and c containing v
                    chain = []
                    visited = set()
                    queue = [v]
                    visited.add(v)
                    while queue:
                        u = queue.pop()
                        chain.append(u)
                        for w in adj[u]:
                            if w not in visited and colors[w] in (max_c, c):
                                visited.add(w)
                                queue.append(w)
                    # Swap
                    for u in chain:
                        colors[u] = c if colors[u] == max_c else max_c
                    if colors[v] != max_c:
                        swapped = True
                        break
                    else:
                        for u in chain:
                            colors[u] = max_c if colors[u] == c else c
                if not swapped:
                    all_done = False
            if not all_done:
                break
        return colors

    best_colors = None
    best_count = float('inf')

    def update_best(c):
        nonlocal best_colors, best_count
        cnt = max(c) + 1
        if cnt < best_count:
            best_count = cnt
            best_colors = c[:]

    # Initial constructions
    update_best(dsatur_color(noise=0.0))
    update_best(rlf_color())
    for _ in range(6):
        update_best(dsatur_color(noise=1.0))

    # Apply Kempe reduction on best
    reduced = kempe_reduce(best_colors)
    update_best(reduced)

    # More restarts then reduce again
    for _ in range(4):
        c = dsatur_color(noise=1.0)
        c = kempe_reduce(c)
        update_best(c)

    return best_colors

