                if colors[nb] == -1:
                    if c not in colored_neighbors[nb]:
                        colored_neighbors[nb].add(c)
                        saturation[nb] += 1
        return colors

    def recolor_vertices(colors, uncolored_verts):
        colors = colors[:]
        for v in uncolored_verts:
            colors[v] = -1

        saturation = [0] * n
        colored_neighbors = [set() for _ in range(n)]
        for v in range(n):
            if colors[v] >= 0:
                for nb in adj[v]:
                    if colors[nb] == -1:
                        if colors[v] not in colored_neighbors[nb]:
                            colored_neighbors[nb].add(colors[v])
                            saturation[nb] += 1

        remaining = list(uncolored_verts)
        degree = [len(adj[i]) for i in range(n)]
        remaining_set = set(remaining)

        while remaining_set:
            v = max(remaining_set, key=lambda x: (saturation[x], degree[x]))
            remaining_set.remove(v)
            used = colored_neighbors[v]
            c = 0
            while c in used:
                c += 1
            colors[v] = c
            for nb in adj[v]:
                if nb in remaining_set:
                    if c not in colored_neighbors[nb]:
                        colored_neighbors[nb].add(c)
                        saturation[nb] += 1
        return colors

    def kempe_reduce(colors):
        num_colors = max(colors) + 1
        color_classes = [[] for _ in range(num_colors)]
        for v, c in enumerate(colors):
            color_classes[c].append(v)

        # Try to eliminate the smallest color class via Kempe chains
        for target in sorted(range(num_colors), key=lambda c: len(color_classes[c])):
            verts = color_classes[target][:]
            new_colors = colors[:]
            success = True
            for v in verts:
                # Try to recolor v with any other color via Kempe swap
                nb_colors = {new_colors[nb] for nb in adj[v]}
                alt = next((c for c in range(num_colors) if c != target and c not in nb_colors), None)
                if alt is not None:
                    new_colors[v] = alt
                else:
                    success = False
                    break
            if success:
                return new_colors
        return colors

    best = dsatur_color()
    best_k = max(best) + 1

    rng = random.Random(42)

    for iteration in range(80):
        colors = best[:]
        num_colors = max(colors) + 1
        color_classes = [[] for _ in range(num_colors)]
        for v, c in enumerate(colors):
            color_classes[c].append(v)

        # Remove smallest color classes to force recoloring
        sizes = sorted(range(num_colors), key=lambda c: len(color_classes[c]))
        num_remove = max(1, min(3, num_colors // 8))
        if iteration % 5 == 0:
            num_remove = max(1, min(5, num_colors // 5))

        to_uncolor = set()
        for c in sizes[:num_remove]:
            to_uncolor.update(color_classes[c])

        new_colors = recolor_vertices(colors, to_uncolor)
        new_colors = kempe_reduce(new_colors)
        new_k = max(new_colors) + 1

        if new_k <= best_k:
            best = new_colors
            best_k = new_k

    # Compact colors
    mapping = {}
    result = []
    for c in best:
        if c not in mapping:
            mapping[c] = len(mapping)
        result.append(mapping[c])
    return result

