    import random
    n = len(adj)
    if n == 0:
        return []

    adj_sets = [set(a) for a in adj]

    def greedy_color(order, colors, fixed=None):
        # fixed: set of vertices whose colors are fixed
        if fixed is None:
            fixed = set()
        for v in order:
            if v in fixed:
                continue
            used = {colors[u] for u in adj[v] if colors[u] >= 0}
            c = 0
            while c in used:
                c += 1
            colors[v] = c
        return colors

    def dsatur_order():
        colors = [-1] * n
        saturation = [0] * n
        degree = [len(adj[v]) for v in range(n)]
        colored = [False] * n
        neighbor_colors = [set() for _ in range(n)]
        order = []
        for _ in range(n):
            best = -1
            for v in range(n):
                if colored[v]:
                    continue
                if best == -1 or (saturation[v], degree[v]) > (saturation[best], degree[best]):
                    best = v
            order.append(best)
            used = set()
            for u in adj[best]:
                used |= {colors[u]} if colors[u] >= 0 else set()
            c = 0
            while c in used:
                c += 1
            colors[best] = c
            colored[best] = True
            for u in adj[best]:
                if not colored[u] and c not in neighbor_colors[u]:
                    neighbor_colors[u].add(c)
                    saturation[u] += 1
        return colors

    def kempe_chain_reduce(colors, target_color):
        # Try to eliminate target_color by Kempe chain swaps with smaller colors
        vertices_with_target = [v for v in range(n) if colors[v] == target_color]
        for v in vertices_with_target:
            if colors[v] != target_color:
                continue
            # Try swapping with each smaller color
            for alt in range(target_color):
                if any(colors[u] == alt for u in adj[v]):
                    continue
                # Can directly recolor v to alt
                colors[v] = alt
                break
            else:
                # Try Kempe chain swap between target_color and some alt color
                for alt in range(target_color):
                    # Build Kempe chain for (target_color, alt) containing v
                    chain = []
                    stack = [v]
                    visited = set()
                    while stack:
                        u = stack.pop()
                        if u in visited:
                            continue
                        visited.add(u)
                        chain.append(u)
                        for w in adj[u]:
                            if w not in visited and colors[w] in (target_color, alt):
                                stack.append(w)
                    # Check if swapping this chain is safe (it always is for Kempe chains)
                    # Swap colors in chain
                    for u in chain:
                        colors[u] = alt if colors[u] == target_color else target_color
                    # Check if v now has no target_color neighbors conflict
                    if colors[v] == alt:
                        break
                    else:
                        # Undo swap
                        for u in chain:
                            colors[u] = target_color if colors[u] == alt else alt
        return colors

    def iterated_greedy(colors, iterations=40):
        best = colors[:]
        best_k = max(best) + 1
        cur = colors[:]

        for it in range(iterations):
            k = max(cur) + 1
            # Find largest color class to destroy
            class_sizes = [0] * k
            for c in cur:
                class_sizes[c] += 1
            # Remove the largest color class vertices
            target = max(range(k), key=lambda c: class_sizes[c])
            freed = [v for v in range(n) if cur[v] == target]
            for v in freed:
                cur[v] = -1
            # Reorder freed vertices by saturation descending
            sat = []
            for v in freed:
                s = len({cur[u] for u in adj[v] if cur[u] >= 0})
                sat.append((s, len(adj[v]), v))
            sat.sort(reverse=True)
            order = [x[2] for x in sat]
            cur = greedy_color(order, cur)
            cur = kempe_chain_reduce(cur, max(cur))
            if max(cur) + 1 < best_k:
                best = cur[:]
                best_k = max(best) + 1
            # Shuffle for diversity
            if it % 10 == 9:
                cur = best[:]
        return best

    colors = dsatur_order()
    colors = iterated_greedy(colors)

    # Final validation fix
    for v in range(n):
        used = {colors[u] for u in adj[v]}
        if colors[v] in used:
            c = 0
            while c in used:
                c += 1
            colors[v] = c

    return colors

