            nc = neighbor_colors[v]
            while c in nc:
                c += 1
            colors[v] = c
            for u in adj[v]:
                neighbor_colors[u].add(c)
        return colors

    def smallest_last_order():
        degree = [len(adj[v]) for v in range(n)]
        removed = [False] * n
        buckets = [[] for _ in range(n)]
        for v in range(n):
            buckets[degree[v]].append(v)
        order = []
        for _ in range(n):
            for d in range(n):
                while buckets[d] and removed[buckets[d][-1]]:
                    buckets[d].pop()
                if buckets[d]:
                    v = buckets[d].pop()
                    removed[v] = True
                    order.append(v)
                    for u in adj[v]:
                        if not removed[u]:
                            old_d = degree[u]
                            degree[u] -= 1
                            buckets[degree[u]].append(u)
                    break
        return order[::-1]

    def kempe_swap(colors, c1, c2, start):
        # Flip colors c1<->c2 in the connected component of 'start' in subgraph induced by c1,c2
        new_colors = colors[:]
        stack = [start]
        visited = {start}
        while stack:
            v = stack.pop()
            if new_colors[v] == c1:
                new_colors[v] = c2
            else:
                new_colors[v] = c1
            for u in adj[v]:
                if u not in visited and new_colors[u] in (c1, c2):
                    visited.add(u)
                    stack.append(u)
        return new_colors

    def try_merge_colors(colors, num_colors):
        # Try to eliminate the smallest color class by reassigning via Kempe swaps
        from collections import defaultdict
        class_sizes = defaultdict(int)
        for c in colors:
            class_sizes[c] += 1
        sorted_classes = sorted(class_sizes, key=lambda c: class_sizes[c])

        best = colors[:]
        best_nc = num_colors
        # Try to eliminate smallest class
        for target in sorted_classes[:3]:
            trial = colors[:]
            success = True
            for v in range(n):
