        colors = [-1] * n
        saturation = [0] * n
        degree = [len(adj[i]) for i in range(n)]
        colored_neighbors = [set() for _ in range(n)]
        import heapq
        heap = [(-0, -degree[i], i) for i in range(n)]
        heapq.heapify(heap)
        colored = [False] * n
        for _ in range(n):
            while True:
                sat, deg, u = heapq.heappop(heap)
                if not colored[u]:
                    break
            used = colored_neighbors[u]
            c = 0
            while c in used:
                c += 1
            colors[u] = c
            colored[u] = True
            for v in adj[u]:
                if not colored[v]:
                    if c not in colored_neighbors[v]:
                        colored_neighbors[v].add(c)
                        saturation[v] += 1
                        heapq.heappush(heap, (-saturation[v], -degree[v], v))
        return colors

    def greedy_color_ordered(order, colors):
        for u in order:
            used = set()
            for v in adj[u]:
                if colors[v] >= 0:
                    used.add(colors[v])
            c = 0
            while c in used:
                c += 1
            colors[u] = c

    def try_kempe_reduce(colors, num_colors):
        # Try to eliminate the largest color index by Kempe chain swaps
        # Find color class sizes
        from collections import defaultdict
        class_members = defaultdict(list)
        for v, c in enumerate(colors):
            class_members[c].append(v)

        # Try to recolor vertices of the last color class
        target = num_colors - 1
        members = class_members[target][:]
        random.shuffle(members)

        new_colors = colors[:]
        for v in members:
            used = set()
            for u in adj[v]:
                used.add(new_colors[u])
            # Try to assign a color < target
            assigned = False
            for c in range(target):
                if c not in used:
                    new_colors[v] = c
                    assigned = True
                    break
            if not assigned:
                return colors, num_colors  # failed
        return new_colors, target

    def iterated_greedy(colors, max_iter=40):
        from collections import defaultdict
        best = colors[:]
        best_k = max(colors) + 1

        for iteration in range(max_iter):
            class_members = defaultdict(list)
            for v, c in enumerate(best):
                class_members[c].append(v)
            k = max(best) + 1

            # Sort classes by size ascending, uncolor smallest ones
            sizes = sorted(class_members.keys(), key=lambda c: len(class_members[c]))
            # Uncolor bottom fraction
            num_uncolor = max(1, k // 8)
            uncolor_set = set()
            for c in sizes[:num_uncolor]:
                for v in class_members[c]:
                    uncolor_set.add(v)

            new_colors = best[:]
            for v in uncolor_set:
                new_colors[v] = -1

            # Reorder uncolored by saturation (descending)
            sat = {}
            for v in uncolor_set:
                used = set()
                for u in adj[v]:
                    if new_colors[u] >= 0:
                        used.add(new_colors[u])
