            new_k = max(new_colors) + 1
            if new_k < best_k:
                best = new_colors[:]
                best_k = new_k
            elif random.random() < 0.3:
                best = new_colors[:]
                best_k = new_k

        return best, best_k

    colors = dsatur_color()
    num_colors = max(colors) + 1

    # Try Kempe reduction passes
    for _ in range(5):
        new_colors, new_k = try_kempe_reduce(colors, num_colors)
        if new_k < num_colors:
