import random

def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []

    def dsatur_color(n, adj, forbidden_colors=None):
        colors = [-1] * n
        saturation = [0] * n
        colored_neighbors = [set() for _ in range(n)]
        degree = [len(adj[v]) for v in range(n)]
        import heapq
        heap = [(-0, -degree[v], v) for v in range(n)]
        heapq.heapify(heap)
        colored = [False] * n

        for _ in range(n):
            while True:
                neg_sat, neg_deg, v = heapq.heappop(heap)
                if not colored[v]:
                    break
            forbidden = colored_neighbors[v]
            if forbidden_colors and forbidden_colors[v] is not None:
                forbidden = forbidden | {forbidden_colors[v]}
            c = 0
            while c in forbidden:
                c += 1
            colors[v] = c
            colored[v] = True
            for u in adj[v]:
                if not colored[u]:
                    colored_neighbors[u].add(c)
                    saturation[u] = len(colored_neighbors[u])
                    heapq.heappush(heap, (-saturation[u], -degree[u], u))
        return colors

    def greedy_color(order, adj, num_colors_hint=None):
        n = len(order)
        colors = [-1] * len(adj)
        for v in order:
            used = set()
            for u in adj[v]:
                if colors[u] >= 0:
                    used.add(colors[u])
            c = 0
            while c in used:
                c += 1
            colors[v] = c
        return colors

    def kempe_chain_reduce(colors, adj, n):
        num_colors = max(colors) + 1
        improved = True
        while improved:
            improved = False
            color_counts = [0] * num_colors
            for c in colors:
                color_counts[c] += 1
            # Try to eliminate smallest color class
            target = min(range(num_colors), key=lambda c: color_counts[c])
            target_verts = [v for v in range(n) if colors[v] == target]

            for v in target_verts:
                # Try to recolor v using kempe chain swap
                neighbor_colors = set(colors[u] for u in adj[v])
                for alt_color in range(num_colors):
                    if alt_color == target or alt_color in neighbor_colors:
                        continue
                    # Swap colors between alt_color and target in v's component
                    # Find kempe chain: vertices reachable from v using colors {target, alt_color}
                    chain = []
                    stack = [v]
                    visited = set()
                    while stack:
                        node = stack.pop()
                        if node in visited:
                            continue
                        visited.add(node)
                        chain.append(node)
                        for u in adj[node]:
                            if u not in visited and colors[u] in (target, alt_color):
                                stack.append(u)
                    # Swap colors in chain
                    for node in chain:
                        if colors[node] == target:
                            colors[node] = alt_color
                        else:
                            colors[node] = target
                    break

            new_num = max(colors) + 1
            # Compact colors
            used = sorted(set(colors))
            remap = {c: i for i, c in enumerate(used)}
            colors = [remap[c] for c in colors]
            num_colors = max(colors) + 1
            if num_colors < (max(colors) + 1 if colors else 1) or len(set(colors)) < len(used):
                improved = True
        return colors

    def iterated_greedy(colors, adj, n, iterations=40):
        best = colors[:]
        best_k = max(best) + 1

        for it in range(iterations):
            k = max(best) + 1
            # Sort colors by class size descending, vertices by color then degree
            color_sizes = {}
            for c in best:
                color_sizes[c] = color_sizes.get(c, 0) + 1

            # Destroy: remove top ceil(k/3) colors, reassign those vertices
            num_remove = max(1, k // 4)
            sorted_colors = sorted(range(k), key=lambda c: color_sizes.get(c, 0))
            remove_set = set(sorted_colors[:num_remove])

            partial = best[:]
            to_reassign = [v for v in range(n) if partial[v] in remove_set]
            for v in to_reassign:
                partial[v] = -1

            # Reassign by degree desc
            to_reassign.sort(key=lambda v: -len(adj[v]))
            for v in to_reassign:
                used = set()
                for u in adj[v]:
                    if partial[u] >= 0:
                        used.add(partial[u])
                c = 0
                while c in used:
                    c += 1
                partial[v] = c

            # Compact
            used_c = sorted(set(partial))
            remap = {c: i for i, c in enumerate(used_c)}
            partial = [remap[c] for c in partial]
            new_k = max(partial) + 1

            if new_k < best_k:
                best = partial
                best_k = new_k

        return best

    # Step 1: Initial DSATUR coloring
    colors = dsatur_color(n, adj)

    # Step 2: Kempe chain reduction
    colors = kempe_chain_reduce(colors, adj, n)

    # Step 3: Iterated greedy improvement
    colors = iterated_greedy(colors, adj, n, iterations=50)

